/**
 * @description Data-free tests of the payload logic: in-memory records and Schema checks only, no DML or queries.
 */
@IsTest
private class IntegrationHubPayloadTest {

    private static final String STUB_CLASS = 'IntegrationHubTestData.StubPayloadBuilder';

    @IsTest
    static void bodyHasTypedValuesAndLeavesOutNulls() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            IH_Connection__c rec = (IH_Connection__c) JSON.deserialize('{"attributes":{"type":"IH_Connection__c"},'
                + '"Id":"' + fakeId(IH_Connection__c.SObjectType, 1) + '","Name":"Acme","CreatedDate":"2024-05-01T10:20:30.000+0000",'
                + '"Timeout_Seconds__c":10,"Active__c":true,"Inbound_User__r":{"attributes":{"type":"User"},"Name":"Ann"}}', IH_Connection__c.class);
            IH_Transaction__c t = txn(1, rec.Id);
            List<String> paths = IntegrationHubPayloadPaths.split('Name, CreatedDate\nTimeout_Seconds__c;Active__c,Inbound_User__r.Name,'
                + 'Named_Credential__c,Owner.Name');
            Map<String, Object> body = IntegrationHubPayload.baseBody('txnId', t);
            body.put('fields', IntegrationHubPayload.fieldValues(rec, paths));
            String sent = JSON.serialize(body, true);
            Assert.isTrue(sent.contains('"txnId":"' + t.Id + '"'), 'the transaction Id is under the chosen key: ' + sent);
            Assert.isTrue(sent.contains('"CreatedDate":"2024-05-01T10:20:30.000Z"'), 'Datetimes are ISO UTC: ' + sent);
            Assert.isTrue(sent.contains('"Timeout_Seconds__c":10'), 'numbers stay numbers: ' + sent);
            Assert.isTrue(sent.contains('"Active__c":true'), 'booleans stay booleans: ' + sent);
            Assert.isTrue(sent.contains('"Inbound_User__r.Name":"Ann"'), 'parent paths are read: ' + sent);
            Assert.isFalse(sent.contains('Named_Credential__c'), 'empty values are left out: ' + sent);
            Assert.isFalse(sent.contains('Owner.Name'), 'an empty lookup on the way is left out: ' + sent);
            Assert.areEqual(0, IntegrationHubPayload.fieldValues(null, paths).size(), 'no record: no values');
            Assert.isNull(IntegrationHubPayloadPaths.read(null, 'Owner.Name'), 'no record: null');
        }
    }

    @IsTest
    static void pathsAreSplitAndChecked() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            Assert.areEqual(new List<String>{ 'Name', 'Phone' }, IntegrationHubPayloadPaths.split(' Name; name\n\nPhone,'),
                'paths are trimmed, split and de-duplicated in order');
            Assert.areEqual(0, IntegrationHubPayloadPaths.split(null).size(), 'blank text: no paths');
            Assert.isNull(IntegrationHubPayloadPaths.invalid('IH_Connection__c', new List<String>{ 'Name', 'Owner.Name', 'inbound_user__r.email' }),
                'valid fields, lookups and any case pass');
            String bad = IntegrationHubPayloadPaths.invalid('IH_Connection__c', new List<String>{ 'Name', 'Owner.No_Such__c', 'Nope.Name' });
            Assert.isTrue(bad.contains('Owner.No_Such__c') && bad.contains('Nope.Name') && !bad.contains('Name,'), 'only bad paths are named: ' + bad);
            Assert.isNotNull(IntegrationHubPayloadPaths.invalid('No_Such_Object__x', new List<String>{ 'Name' }), 'unknown object');
            Assert.isNull(IntegrationHubPayloadPaths.invalid(null, new List<String>()), 'no object and no paths is fine');
            Assert.isNotNull(IntegrationHubPayloadPaths.invalid('Account', new List<String>{ 'Owner.Manager.Manager.Manager.Manager.Manager.Name' }),
                'more than five lookups is refused');
            Assert.areEqual('sfTransactionId', IntegrationHubPayload.txnKeyOf(new IH_Event__c()), 'default transaction key');
            Assert.areEqual('ref', IntegrationHubPayload.txnKeyOf(new IH_Event__c(Transaction_Id_Key__c = 'ref')), 'chosen transaction key');
        }
    }

    @IsTest
    static void selectedFieldsWithoutQueryOrWithBadPaths() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            List<IH_Transaction__c> txns = new List<IH_Transaction__c>{ txn(1, fakeId(IH_Connection__c.SObjectType, 1)) };
            Assert.areEqual(0, IntegrationHubPayload.build(new IH_Event__c(), new List<IH_Transaction__c>()).bodies.size(), 'no transactions');
            IntegrationHubPayload.Result plain = IntegrationHubPayload.build(new IH_Event__c(Related_Object__c = 'IH_Connection__c'), txns);
            Assert.isTrue(plain.bodies.get(txns[0].Id).contains('"recordId"'), 'no fields: the base body is built without a query');
            IntegrationHubPayload.Result bad = IntegrationHubPayload.build(
                new IH_Event__c(Payload_Source__c = 'Selected Fields', Payload_Fields__c = 'No_Such__c'), txns);
            Assert.isTrue(bad.errors.get(txns[0].Id).contains('No_Such__c'), 'a bad path fails the transaction');
        }
    }

    @IsTest
    static void storedCopyCutsLongPayloads() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            Assert.areEqual('{"a":1}', IntegrationHubOutcome.storedCopy('{"a":1}'), 'a short payload is stored as it is');
            Assert.isNull(IntegrationHubOutcome.storedCopy(null), 'no payload stays empty');
            String exact = 'x'.repeat(131072);
            Assert.areEqual(exact, IntegrationHubOutcome.storedCopy(exact), 'a payload that fits exactly is kept');
            String stored = IntegrationHubOutcome.storedCopy('x'.repeat(140000));
            Assert.areEqual(131072, stored.length(), 'the stored copy fits the field exactly');
            Assert.isTrue(stored.contains('140000 characters'), 'the stored copy says how long the sent payload was');
        }
    }

    @IsTest
    static void classResultsAreApplied() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            List<IH_Transaction__c> txns = threeTxns();
            Map<Id, Object> results = new Map<Id, Object>{
                (Id) txns[0].Related_Record_Id__c => new Map<String, Object>{ 'a' => 1 },
                (Id) txns[1].Related_Record_Id__c => '<xml/>'
            };
            IntegrationHubPayload.Result r = IntegrationHubPayloadClass.apply(results, txns, 'tid');
            Map<String, Object> mapBody = (Map<String, Object>) JSON.deserializeUntyped(r.bodies.get(txns[0].Id));
            Assert.areEqual(String.valueOf(txns[0].Id), mapBody.get('tid'), 'a Map gets the transaction Id key');
            Assert.areEqual(1, mapBody.get('a'), 'a Map keeps its values');
            Assert.areEqual('<xml/>', r.bodies.get(txns[1].Id), 'a String is sent as it is');
            Assert.areEqual('Payload class returned nothing for record ' + txns[2].Related_Record_Id__c, r.errors.get(txns[2].Id),
                'a missing result fails the transaction');
            IntegrationHubPayload.Result none = IntegrationHubPayloadClass.apply(null, txns, 'tid');
            Assert.areEqual(3, none.errors.size(), 'a null result map fails every transaction');
            IntegrationHubPayload.Result failed = IntegrationHubPayloadClass.failAll(txns, 'Broken');
            Assert.areEqual('Broken', failed.errors.get(txns[0].Id), 'a class problem fails every transaction');
            Assert.areEqual(0, failed.bodies.size(), 'no body is sent when the class failed');
        }
    }

    @IsTest
    static void classIsCalledOnceForTheBatch() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            List<IH_Transaction__c> txns = threeTxns();
            IH_Event__c ev = new IH_Event__c(Event_Key__c = 'K', Payload_Source__c = 'Apex Class', Payload_Class__c = STUB_CLASS);
            IntegrationHub.PayloadRequest req = IntegrationHubPayloadClass.request(ev, txns);
            Assert.areEqual(3, req.recordIds.size(), 'every record Id once');
            Assert.areEqual('IH_Connection__c', req.relatedObject, 'the object falls back to the transactions');
            Assert.areEqual(txns[1].Id, req.transactionIdByRecordId.get((Id) txns[1].Related_Record_Id__c), 'transaction per record');
            IntegrationHubPayload.Result r = IntegrationHubPayload.build(ev, txns);
            Assert.isTrue(r.bodies.get(txns[0].Id).contains('"batch":3'), 'the class saw the whole batch in one call');
            Assert.areEqual('{"kind":"string"}', r.bodies.get(txns[1].Id), 'String result sent as is');
            Assert.isTrue(r.errors.containsKey(txns[2].Id), 'nothing for the third record fails it');
        }
    }

    @IsTest
    static void classProblemsFailPermanently() {
        System.runAs(new User(Id = UserInfo.getUserId())) {
            List<IH_Transaction__c> txns = threeTxns();
            Assert.isTrue(errorFor(new IH_Event__c(Payload_Class__c = 'No_Such_Builder'), txns).contains('Class not found'),
                'a missing class is named');
            Assert.isTrue(errorFor(new IH_Event__c(Payload_Class__c = 'IntegrationHubTestData.StubResponse'), txns)
                .contains('does not implement IntegrationHub.IPayloadBuilder'), 'a class with the wrong interface is refused');
            Assert.isTrue(errorFor(new IH_Event__c(Event_Key__c = 'BOOM', Payload_Class__c = STUB_CLASS), txns).contains('Builder crashed'),
                'an exception in the class is kept');
        }
    }

    private static String errorFor(IH_Event__c ev, List<IH_Transaction__c> txns) {
        ev.Payload_Source__c = 'Apex Class';
        IntegrationHubPayload.Result r = IntegrationHubPayload.build(ev, txns);
        Assert.areEqual(txns.size(), r.errors.size(), 'every transaction fails');
        return r.errors.get(txns[0].Id);
    }

    private static List<IH_Transaction__c> threeTxns() {
        return new List<IH_Transaction__c>{
            txn(1, fakeId(IH_Connection__c.SObjectType, 1)),
            txn(2, fakeId(IH_Connection__c.SObjectType, 2)),
            txn(3, fakeId(IH_Connection__c.SObjectType, 3))
        };
    }

    private static IH_Transaction__c txn(Integer n, Id recordId) {
        return new IH_Transaction__c(Id = fakeId(IH_Transaction__c.SObjectType, n), Event_Name__c = 'K',
            Related_Record_Id__c = recordId, Related_Object__c = 'IH_Connection__c');
    }

    private static Id fakeId(Schema.SObjectType objType, Integer n) {
        String num = String.valueOf(n);
        return Id.valueOf(objType.getDescribe().getKeyPrefix() + '0'.repeat(12 - num.length()) + num);
    }
}
